const __RB_WASM_B64 = "";

let __rbWasmModule: WebAssembly.Module | null = null;

async function getRbWasmModule(): Promise<WebAssembly.Module> {
  if (__rbWasmModule) return __rbWasmModule;
  const bin = atob(__RB_WASM_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  __rbWasmModule = await WebAssembly.compile(bytes.buffer);
  return __rbWasmModule;
}

async function initHarmonyWorker(worker: Worker): Promise<void> {
  const wasmModule = await getRbWasmModule();
  return new Promise((resolve, reject) => {
    const id = Date.now();
    const timeout = setTimeout(() => reject(new Error('Worker init timeout')), 30000);
    worker.addEventListener('message', function handler(e) {
      if (e.data.id !== id) return;
      clearTimeout(timeout);
      worker.removeEventListener('message', handler);
      if (e.data.type === 'initDone') resolve();
      else reject(new Error(e.data.message || 'Worker init error'));
    });
    // WebAssembly.Module est transférable — zéro copie mémoire
    worker.postMessage({ id, op: 'init', wasmModule, umdCode: __RB_UMD_CODE }, []);
  });
}

